#!/usr/bin/env node
// Post-build fix for a tsup/esbuild+Rollup toolchain gap: the CJS artifact
// (dist/**/*.js) is generated by tsup's tree-shaking pass, which — for
// splitting/treeshake builds — has esbuild emit ESM, then hands that to
// Rollup's `bundle.generate({ format: 'cjs' })` to produce the final CJS file
// (tsup has no config knob into this stage). Rollup >=3 defaults
// `output.dynamicImportInCjs: true`, so any `import(...)` in the source
// survives as a literal ESM-only `import(...)` expression inside a CJS file.
//
// That is fatal in any CJS VM that has not opted into
// `--experimental-vm-modules` — Jest (incl. jest-expo, the standard React
// Native / Expo test runner), ts-node's CJS mode, and plain `require()`
// consumers generally. It throws: "A dynamic import callback was invoked
// without --experimental-vm-modules".
//
// Fix: after tsup finishes, walk dist/**/*.js (the CJS output only — *.mjs is
// never touched) and run every file that contains the substring `import(`
// through `esbuild.transformSync` with `supported: { 'dynamic-import': false
// }`. That lowers `import(x)` to `Promise.resolve().then(() => require(x))`
// — same deferred-until-called laziness as the source `import()`, expressed
// in syntax every CJS VM can execute. esbuild also injects a `__toESM`-style
// interop wrapper around the `require(...)` result, so the resolved value
// keeps a `.default` — the existing call sites already do
// `(mod as {default?}).default ?? mod`, so no source change is needed.
//
// This intentionally does NOT touch the ESM artifact (*.mjs): bundlers
// (Rollup/Rspack/webpack/Vite/Metro) and edge runtimes (workerd) all resolve
// the `import` condition, and code-splitting / laziness there is measured by
// `verify:treeshake` and `budgets:check` — both must stay green with
// unchanged numbers, which is itself proof the ESM artifact was untouched.
//
// target/minify are kept in lockstep with tsup.config.ts so files this
// script does NOT need to touch (no `import(` substring) are never opened,
// and files it does touch shift in the same way tsup itself would minify
// them — no unrelated bundle-size drift.
//
// Sourcemaps: for every file this script actually rewrites, the adjacent
// `.js.map` is deleted and any trailing `//# sourceMappingURL=` comment is
// stripped from the rewritten file. scripts/verify-build.js asserts nothing
// about maps. This is a CJS-only regression — the .mjs build keeps full
// sourcemaps. The CJS artifact is the runtime-compat target; the ESM
// artifact stays the debuggable one.

import { readFileSync, writeFileSync, existsSync, unlinkSync, readdirSync, statSync } from 'node:fs';
import { join, extname, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as esbuild from 'esbuild';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const distDir = join(root, 'dist');

// Must match tsup.config.ts exactly — see header comment.
const TARGET = 'es2020';
const MINIFY = true;

const SOURCEMAP_COMMENT_RE = /\n?\/\/# sourceMappingURL=[^\n]*/g;

function walkJsFiles(dir, out = []) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory()) {
      walkJsFiles(full, out);
    } else if (extname(entry) === '.js') {
      // extname('.js') excludes .mjs, .d.ts (extname === '.ts'), and
      // *.js.map (extname === '.map').
      out.push(full);
    }
  }
  return out;
}

if (!existsSync(distDir)) {
  console.error('downlevel-cjs-dynamic-import: dist/ not found — run this after tsup, not standalone.');
  process.exit(1);
}

const jsFiles = walkJsFiles(distDir);
let rewritten = 0;

for (const file of jsFiles) {
  const code = readFileSync(file, 'utf8');
  if (!code.includes('import(')) continue;

  // BLOCKER 1 (fix-nextjs-appouter-build-and-redirect-header-leak) safety
  // net: this script runs AFTER tsup's own `onSuccess` hook, which already
  // ran scripts/fix-use-client-directive.mjs and may have hoisted a
  // `"use client";` directive to this exact file's first statement (see
  // that script's header — none of the files it touches currently also
  // contain `import(`, so this branch is a defensive assertion, not a fix
  // that runs in practice today). esbuild's minifier preserves a leading
  // directive prologue by spec, so re-transforming should never lose it —
  // verify that invariant explicitly and fail loudly instead of silently
  // shipping a build where Next.js's App Router support regressed.
  const hadLeadingUseClient = /^(["'])use client\1;/.test(code);

  const result = esbuild.transformSync(code, {
    format: 'cjs',
    target: TARGET,
    minify: MINIFY,
    legalComments: 'none',
    supported: { 'dynamic-import': false },
  });

  if (hadLeadingUseClient && !/^(["'])use client\1;/.test(result.code)) {
    console.error(
      `downlevel-cjs-dynamic-import: ${relative(root, file)} had a leading "use client" directive ` +
        'before this transform and lost it afterward — esbuild re-minification is expected to ' +
        'preserve a leading directive prologue. Refusing to ship a build that silently regresses ' +
        'the Next.js App Router "use client" fix (scripts/fix-use-client-directive.mjs).',
    );
    process.exit(1);
  }

  const cleaned = result.code.replace(SOURCEMAP_COMMENT_RE, '');
  writeFileSync(file, cleaned);

  const mapFile = `${file}.map`;
  if (existsSync(mapFile)) {
    unlinkSync(mapFile);
  }

  rewritten += 1;
  console.log(`downlevel-cjs-dynamic-import: rewrote ${relative(root, file)}`);
}

console.log(`downlevel-cjs-dynamic-import: ${rewritten} file(s) rewritten.`);
